import{_ as t,o as l,c as r,aA as i}from"./chunks/framework.BMzE2Z9R.js";const h=JSON.parse('{"title":"3C原则","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/theory/3c.md","filePath":"nars/theory/3c.md","lastUpdated":1778399398000}'),a={name:"nars/theory/3c.md"};function o(s,e,n,p,c,_){return l(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_3c原则" tabindex="-1">3C原则 <a class="header-anchor" href="#_3c原则" aria-label="Permalink to &quot;3C原则&quot;">​</a></h1><p>🔗<a href="http://agi-society.cn/wiki/index.php/3C%E5%8E%9F%E5%88%99" target="_blank" rel="noreferrer">旧版Wiki↗</a></p><p><a href="./gti/chapter6/6.2">原版解释@GTI</a>（<a href="https://cis.temple.edu/~pwang/GTI-book/GTI-CH6/GTI-6-2.html" target="_blank" rel="noreferrer">GitHub↗</a>）</p><ol><li><p><strong>正确</strong>性(Correctness)</p><ul><li>科学知识需要被社会广泛接受。一个理论需要与人们广泛的经验相一致，才能被视为科学。</li></ul></li><li><p><strong>具体</strong>性(Concreteness)</p><ul><li>科学理论需要具备指导性，为人们的行动提供指导。一个好的理论不能只提出模糊的原则，需要能对未来情况做出具体的预测。</li></ul></li><li><p><strong>紧凑</strong>性(Compactness)</p><ul><li>科学理论需要对大量的具体经验进行归纳、抽象和推广，使知识量最大化地压缩在一个紧凑的结构中，以提高传播和应用的效率。</li></ul></li></ol><p>另一种解释：</p><ul><li>Correctness 正确性 <ul><li>贴近客观事实的经验或证据）</li></ul></li><li>Concreteness 指导性 <ul><li>总结经验并指导行为）</li></ul></li><li>Compactness 简洁性 <ul><li>奥卡姆剃刀） 三者同时独立存在，并同时满足时， 一个理论就趋向完备。</li></ul></li></ul><p>三者缺一不可。</p><p>王培教授在下面这个视频的第20分15秒，有详细讲述：</p><p><a href="https://www.bilibili.com/video/BV1Hp4y1W7ty?p=26" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Hp4y1W7ty?p=26</a></p>',9)])])}const d=t(a,[["render",o]]);export{h as __pageData,d as default};
